// FactCustomerFeedback — generated by src/powerbi/build_assets.py from FactCustomerFeedback.csv
// Grain/keys: see powerbi/data_model.md
let
    Source   = Csv.Document(File.Contents(DataFolder & "FactCustomerFeedback.csv"),
                            [Delimiter = ",", Encoding = 65001, QuoteStyle = QuoteStyle.Csv]),
    Promoted = Table.PromoteHeaders(Source, [PromoteAllScalars = true]),
    Typed    = Table.TransformColumnTypes(Promoted, {
        {"feedback_id", type text},
        {"ticket_id", type text},
        {"customer_id", type text},
        {"feedback_date", type datetime},
        {"satisfaction_score", Int64.Type},
        {"customer_rating", Int64.Type},
        {"feedback_category", type text},
        {"customer_comment", type text},
        {"satisfaction_score_invalid", type logical},
        {"agent_id", type text},
        {"department_id", type text},
        {"first_response_hours", type number},
        {"resolution_hours", type number},
        {"sla_met", Int64.Type},
        {"category_key", Int64.Type},
        {"channel_key", Int64.Type},
        {"priority_key", Int64.Type},
        {"feedback_date_only", type date}
    }, "en-US")
in
    Typed
